1	//! Environment-variable substitution for pnpm-style `${VAR}` placeholders.
2	//!
3	//! Ports pnpm's [`@pnpm/config.env-replace`](https://github.com/pnpm/components/blob/9c2bd17/config/env-replace/env-replace.ts):
4	//! occurrences of `${VAR}` (with optional `${VAR:-default}` fallback) are
5	//! replaced with the value the [`EnvVar`] capability returns for `VAR`.
6	//! Backslashes immediately preceding the `$` escape the placeholder so
7	//! it is left as-is.
8	//!
9	//! The mirrored behaviours are:
10	//! * pattern: `${IDENT}` or `${IDENT:-default}`. `IDENT` is any non-empty
11	//!   sequence that does not contain `$`, `{`, or `}`.
12	//! * even-number-of-backslashes prefix: the placeholder is expanded and
13	//!   half of the backslashes are kept (one literal `\\` per pair).
14	//! * odd-number-of-backslashes prefix: the placeholder is left literal
15	//!   and one backslash is consumed.
16	//! * unset variable + no default: the placeholder is substituted with `""`
17	//!   and recorded in the returned `Vec` so the caller can surface it as a
18	//!   warning, matching `loadNpmrcFiles.ts`'s `substituteEnv` lossy fallback
19	//!   (critical for OIDC trusted publishing — see
20	//!   <https://github.com/pnpm/pnpm/issues/11513>).
21	//! * empty variable + default present: the default wins; this is
22	//!   pnpm's behaviour even though plain shell `${VAR:-default}` would
23	//!   also use the default for the empty case.
24	//!
25	//! The env lookup is threaded through the [`EnvVar`] capability trait so
26	//! callers can drive every branch (set, unset, empty) with local fakes
27	//! instead of mutating the real process environment. Production callers
28	//! thread [`SystemEnv`] (which delegates to `std::env::var`) through the
29	//! turbofish slot; `pacquet-config` threads its broader `Host` provider
30	//! instead, per the DI pattern from
31	//! [pnpm/pacquet#339](https://github.com/pnpm/pacquet/issues/339).
32	
33	/// Capability: read a process environment variable as a UTF-8 string.
34	///
35	/// `pnpm` resolves `${VAR}` placeholders inside `.npmrc` against the
36	/// process environment in
37	/// [`loadNpmrcFiles.ts`](https://github.com/pnpm/pnpm/blob/601317e7a3/config/reader/src/loadNpmrcFiles.ts#L156-L162);
38	/// the lookup is routed through this trait so unit tests can drive every
39	/// branch (set, unset, empty) with local fakes instead of mutating the
40	/// real process environment.
41	pub trait EnvVar {
42	    /// Return the value of the named environment variable, or `None`
43	    /// when it is unset. Implementations should treat invalid UTF-8
44	    /// as `None` to match `std::env::var`'s behaviour, which is what
45	    /// pnpm itself observes via Node's `process.env`.
46	    fn var(name: &str) -> Option<String>;
47	}
48	
49	/// Production [`EnvVar`] provider: reads the real process environment via
50	/// [`std::env::var`].
51	///
52	/// Consumers that don't have their own capability provider thread this
53	/// through the turbofish slot (e.g. `env_replace_lossy::<SystemEnv>(raw)`).
54	/// `pacquet-config` threads its own multi-capability `Host` instead.
55	pub struct SystemEnv;
56	
57	impl EnvVar for SystemEnv {
58	    fn var(name: &str) -> Option<String> {
59	        std::env::var(name).ok()
60	    }
61	}
62	
63	/// Replace every `${VAR}` (or `${VAR:-default}`) placeholder in `text` with
64	/// the value [`Sys::var`] returns. Placeholders that have no value and no
65	/// default become `""` (the literal `${...}` never reaches the caller) and
66	/// are recorded in the returned `Vec` so the caller can surface each one as
67	/// a warning.
68	///
69	/// Mirrors pnpm's `substituteEnv` fallback in
70	/// `config/reader/src/loadNpmrcFiles.ts`: leaving an unresolved `${VAR}` in
71	/// an auth value would later be sent as a literal bearer token, notably
72	/// under OIDC trusted publishing (<https://github.com/pnpm/pnpm/issues/11513>).
73	/// Resolvable placeholders and `${VAR:-default}` fallbacks elsewhere in the
74	/// same string still expand normally — only the unresolved bare ones are
75	/// dropped to `""`.
76	///
77	/// [`Sys::var`]: EnvVar::var
78	#[must_use]
79	pub fn env_replace_lossy<Sys: EnvVar>(text: &str) -> (String, Vec<String>) {
80	    let bytes = text.as_bytes();
81	    let mut output = String::with_capacity(text.len());
82	    let mut unresolved = Vec::new();
83	    let mut index = 0;
84	    while index < bytes.len() {
85	        let char = bytes[index];
86	        if char != b'$' {
87	            output.push(char as char);
88	            index += 1;
89	            continue;
90	        }
91	
92	        // Count backslashes immediately before this `$` in the *source*.
93	        // Counting from `output` would conflate trailing `\` in a
94	        // previously-substituted env value with literal source escapes.
95	        // Upstream's `(?<!\\)(\\*)\$\{...}` runs on the original input.
96	        let mut backslashes = 0;
97	        while backslashes < index && bytes[index - 1 - backslashes] == b'\\' {
98	            backslashes += 1;
99	        }
100	
101	        let Some(end) = find_placeholder_end(bytes, index) else {
102	            output.push('$');
103	            index += 1;
104	            continue;
105	        };
106	
107	        // Each pair of backslashes collapses to one literal backslash,
108	        // matching `(\\*)\$\{...\}` in the JS regex with the escape
109	        // semantics from `replaceEnvMatch`. The source backslashes are
110	        // already in `output` from the literal-passthrough loop, so we
111	        // truncate them off and re-emit half.
112	        output.truncate(output.len() - backslashes);
113	        for _ in 0..(backslashes / 2) {
114	            output.push('\\');
115	        }
116	
117	        let placeholder = &text[index..=end];
118	        if backslashes % 2 == 1 {
119	            // Odd backslashes: the placeholder is escaped, leave it literal.
120	            output.push_str(placeholder);
121	        } else {
122	            let inside = &text[index + 2..end];
123	            let (var_name, default) = match inside.find(":-") {
124	                Some(separator) => (&inside[..separator], Some(&inside[separator + 2..])),
125	                None => (inside, None),
126	            };
127	            let value = Sys::var(var_name).filter(|value| !value.is_empty());
128	            match (value, default) {
129	                (Some(value), _) => output.push_str(&value),
130	                (None, Some(default)) => output.push_str(default),
131	                (None, None) => unresolved.push(placeholder.to_owned()),
132	            }
133	        }
134	        index = end + 1;
135	    }
136	    (output, unresolved)
137	}
138	
139	/// Return the index of the closing `}` for a `${...}` starting at `start`.
140	/// Returns `None` if `text[start..]` is not a well-formed placeholder
141	/// (no opening `{` immediately after `$`, an empty body, or a stray `$`
142	/// or `{` inside the body).
143	fn find_placeholder_end(bytes: &[u8], start: usize) -> Option<usize> {
144	    if bytes.get(start + 1)? != &b'{' {
145	        return None;
146	    }
147	    let body_start = start + 2;
148	    let mut cursor = body_start;
149	    while cursor < bytes.len() {
150	        match bytes[cursor] {
151	            b'}' if cursor > body_start => return Some(cursor),
152	            b'$' | b'{' | b'}' => return None,
153	            _ => cursor += 1,
154	        }
155	    }
156	    None
157	}
