28	/// the fake is a unit struct scoped to the test module; tests
29	/// turbofish it through the generic slot.
30	struct NoEnv;
31	impl EnvVar for NoEnv {
32	    fn var(_: &str) -> Option<String> {
33	        None
34	    }
35	}
